python3 - <<'EOF'
import json
import pathlib

# Normalise every survey definition: sort question keys, rename the old
# "type" field to "kind", drop empty "help" strings, re-indent with 2 spaces.
root = pathlib.Path("definitions")
changed = 0
for path in sorted(root.rglob("*.json")):
    data = json.loads(path.read_text(encoding="utf-8"))
    for section in data.get("sections", []):
        for q in section.get("questions", []):
            if "type" in q:
                q["kind"] = q.pop("type")
            if q.get("help") == "":
                del q["help"]
            if q.get("kind") == "scale" and "range" not in q:
                q["range"] = [1, 5]
        section["questions"] = sorted(section.get("questions", []), key=lambda q: q["id"])
    new = json.dumps(data, indent=2, ensure_ascii=False, sort_keys=True) + "\n"
    if new != path.read_text(encoding="utf-8"):
        path.write_text(new, encoding="utf-8")
        changed += 1
        print("rewrote", path)
print(changed, "file(s) rewritten in place")

# also normalise the translations that mirror the definitions
for path in sorted(pathlib.Path("i18n").glob("*/definitions/*.json")):
    data = json.loads(path.read_text(encoding="utf-8"))
    for key in list(data):
        if key.endswith(".type"):
            data[key[:-5] + ".kind"] = data.pop(key)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, sort_keys=True) + "\n", encoding="utf-8")
EOF
git diff --stat -- definitions | tail -1

