// Allow reports whether a request for key may proceed now.
// It is a shorthand for AllowN(key, time.Now(), 1).
func (l *Limiter) Allow(key string) bool {
	return l.AllowN(key, l.clock.Now(), 1)
}

// AllowN reports whether n requests for key may proceed at time now.
// Buckets idle for longer than l.idleTTL are evicted lazily so the map
// does not grow without bound under high key cardinality.
func (l *Limiter) AllowN(key string, now time.Time, n int) bool {
	if n <= 0 {
		return true
	}
	shard := l.shardFor(key)
	shard.mu.Lock()
	defer shard.mu.Unlock()

	b, ok := shard.buckets[key]
	if !ok {
		b = &bucket{tokens: l.burst, last: now}
		shard.buckets[key] = b
	}
	l.refill(b, now)

	if l.idleTTL > 0 && now.Sub(shard.lastSweep) > l.idleTTL {
		shard.sweep(now, l.idleTTL)
		shard.lastSweep = now
	}

	need := float64(n)
	if b.tokens < need {
		l.metrics.rejected.WithLabelValues(l.name).Inc()
		return false
	}
	b.tokens -= need
	l.metrics.allowed.WithLabelValues(l.name).Add(need)
	return true
}

// refill adds the tokens earned since the last update, capped at burst.
func (l *Limiter) refill(b *bucket, now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens = math.Min(l.burst, b.tokens+elapsed*l.rate)
	b.last = now
}

func (l *Limiter) shardFor(key string) *shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return &l.shards[h.Sum32()%uint32(len(l.shards))]
}

